    // 4 parity bits for each of the 64 hex values
    private val HAM_ENC: IntArray by lazy { ints("""
        0 12 3 15 7 11 4 8 11 7 8 4 12 0 15 3
        13 1 14 2 10 6 9 5 6 10 5 9 1 13 2 14
        14 2 13 1 9 5 10 6 5 9 6 10 2 14 1 13
        3 15 0 12 4 8 7 11 8 4 11 7 15 3 12 0
    """) }

    /** @return fixed hex word (6 bits) or -1 if the word has an uncorrectable error. */
    fun hamming1063(hex6: Int, parity4: Int): Int {
        val v = HAM_DEC[((hex6 and 63) shl 4) or (parity4 and 15)]
        return if (v shr 6 >= 2) -1 else v and 63
    }
    fun hamming1063Parity(hex6: Int): Int = HAM_ENC[hex6 and 63]

    // ---------------------------------------------------------------- GF(64)
    private val EXP = IntArray(126)
    private val LOG = IntArray(64)
    init {
        var x = 1
        for (i in 0 until 63) { EXP[i] = x; LOG[x] = i; x = x shl 1; if (x and 64 != 0) x = x xor 0x43 } // x^6 = x + 1
        for (i in 63 until 126) EXP[i] = EXP[i - 63]
    }
    private fun mul(a: Int, b: Int) = if (a == 0 || b == 0) 0 else EXP[LOG[a] + LOG[b]]
    private fun inv(a: Int) = EXP[63 - LOG[a]]

    /** Generator polynomial coefficients (low degree first) of the t-error-correcting RS code with roots alpha^1..alpha^2t. */
    private fun rsGen(t: Int): IntArray {
        var g = intArrayOf(1)
        for (r in 1..2 * t) {
            val n = IntArray(g.size + 1)
            for (i in g.indices) { n[i + 1] = n[i + 1] xor g[i]; n[i] = n[i] xor mul(g[i], EXP[r]) }
            g = n
        }
        return g
    }
    private val GEN6 by lazy { rsGen(6) }
    private val GEN4 by lazy { rsGen(4) }

    /** Systematic encode: [data] words (k of them, 6 bits each) -> 2t parity words (parity[0] = lowest degree). */
    private fun rsEncode(data: IntArray, t: Int, gen: IntArray): IntArray {
        val np = 2 * t
        val par = IntArray(np)
        for (i in data.size - 1 downTo 0) {
            val fb = data[i] xor par[np - 1]
            for (j in np - 1 downTo 1) par[j] = par[j - 1] xor mul(gen[j], fb)
            par[0] = mul(gen[0], fb)
        }
        return par
    }

    /**
     * Decodes a codeword given as words c[0..n-1] (c[i] = coefficient of x^i; for P25: parity words first, then data).
     * Corrects in place. @return the number of corrected words, or -1 if uncorrectable.
     */
    private fun rsDecode(c: IntArray, t: Int): Int {
        val n2 = 2 * t
        val s = IntArray(n2 + 1) // s[1..2t]
        var any = false
        for (j in 1..n2) {
            var acc = 0
            for (i in c.indices) if (c[i] != 0) acc = acc xor EXP[(LOG[c[i]] + i * j) % 63]
            s[j] = acc; if (acc != 0) any = true
        }
        if (!any) return 0
        // Berlekamp-Massey
        val lam = IntArray(n2 + 2); lam[0] = 1
        var b = IntArray(n2 + 2); b[0] = 1
        var l = 0; var m = 1; var bb = 1
        for (nn in 0 until n2) {
            var d = s[nn + 1]
            for (i in 1..l) d = d xor mul(lam[i], s[nn + 1 - i])
            if (d == 0) { m++ }
            else if (2 * l <= nn) {
                val tmp = lam.copyOf()
                val coef = mul(d, inv(bb))
                for (i in 0 until lam.size - m) lam[i + m] = lam[i + m] xor mul(coef, b[i])
                l = nn + 1 - l; b = tmp; bb = d; m = 1
            } else {
                val coef = mul(d, inv(bb))
                for (i in 0 until lam.size - m) lam[i + m] = lam[i + m] xor mul(coef, b[i])
                m++
            }
        }
        if (l > t) return -1
        // Chien search: position p is in error iff lam(alpha^-p) == 0
        val pos = ArrayList<Int>()
        for (p in 0 until 63) {
            var acc = 0
            for (i in 0..l) if (lam[i] != 0) acc = acc xor EXP[(LOG[lam[i]] + (63 - p) * i) % 63]
            if (acc == 0) pos.add(p)
        }
        if (pos.size != l) return -1
        // omega = S(x) * lam(x) mod x^2t, S(x) = sum S_{j+1} x^j
        val omega = IntArray(n2)
        for (i in 0 until n2) { var acc = 0; for (k in 0..minOf(i, l)) acc = acc xor mul(lam[k], s[i - k + 1]); omega[i] = acc }
        for (p in pos) {
            if (p >= c.size) return -1 // an "error" in the zero-padded part of the shortened code: not a real correction
            val xinv = EXP[(63 - p) % 63]
            var num = 0; var xp = 1
            for (i in 0 until n2) { num = num xor mul(omega[i], xp); xp = mul(xp, xinv) }
            var den = 0; xp = 1 // lam'(x) = sum over odd i of lam[i] x^(i-1)
            var i = 1
            while (i <= l) { den = den xor mul(lam[i], xp); xp = mul(xp, mul(xinv, xinv)); i += 2 }
            if (den == 0) return -1
            c[p] = c[p] xor mul(num, inv(den))
        }
        for (j in 1..n2) { // verify
            var acc = 0
            for (i in c.indices) if (c[i] != 0) acc = acc xor EXP[(LOG[c[i]] + i * j) % 63]
            if (acc != 0) return -1
        }
        return pos.size
    }

    /** Link control: 12 data hex words + 12 parity hex words (RS 24,12,13). Returns corrected data or null. */
    fun rs24_12(data: IntArray, parity: IntArray): IntArray? {
        val c = IntArray(24)
        for (i in 0 until 12) { c[i] = parity[i]; c[12 + i] = data[i] }
        if (rsDecode(c, 6) < 0) return null
        return IntArray(12) { c[12 + it] }
    }
    fun rs24_12Parity(data: IntArray): IntArray = rsEncode(data, 6, GEN6)

    /** Encryption sync: 16 data hex words + 8 parity hex words (RS 24,16,9). */
    fun rs24_16(data: IntArray, parity: IntArray): IntArray? {
        val c = IntArray(24)
        for (i in 0 until 8) c[i] = parity[i]
        for (i in 0 until 16) c[8 + i] = data[i]
        if (rsDecode(c, 4) < 0) return null
        return IntArray(16) { c[8 + it] }
    }
    fun rs24_16Parity(data: IntArray): IntArray = rsEncode(data, 4, GEN4)

    // ---------------------------------------------------------------- NID: BCH(63,16,23)
    /** Generator polynomial of the NID BCH code: product of the distinct minimal polynomials of alpha^1..alpha^22 (degree 47). */
    private val BCH_GEN: Long by lazy {
        val seen = BooleanArray(63); var g = 1L // GF(2) polynomial as bits
        for (i in 1..22) {
            if (seen[i]) continue
            val coset = ArrayList<Int>(); var j = i
            do { coset.add(j); seen[j] = true; j = (j * 2) % 63 } while (j != i)
            var m = intArrayOf(1) // minimal polynomial = prod (x + alpha^j) over the coset (coefficients land in GF(2))
            for (e in coset) {
                val n = IntArray(m.size + 1)
                for (k in m.indices) { n[k + 1] = n[k + 1] xor m[k]; n[k] = n[k] xor mul(m[k], EXP[e]) }
                m = n
            }
            var mp = 0L; for (k in m.indices) { require(m[k] == 0 || m[k] == 1); if (m[k] == 1) mp = mp or (1L shl k) }
            var r = 0L; for (k in 0..62) if ((mp shr k) and 1L != 0L) r = r xor (g shl k)
            g = r
        }
        g
    }

    /** 63-bit NID codeword as a Long (bit 62 = first transmitted bit = MSB of the NAC). */
    fun nidCodeword(nac: Int, duid: Int): Long {
        val d = ((nac and 0xFFF).toLong() shl 4) or (duid and 15).toLong() // 16 data bits
        var rem = d shl 47
        val g = BCH_GEN
        for (i in 62 downTo 47) if ((rem shr i) and 1L != 0L) rem = rem xor (g shl (i - 47))
        return (d shl 47) or (rem and ((1L shl 47) - 1))
    }

    /** DUIDs that exist in P25 Phase 1: HDU 0, TDU 3, LDU1 5, TSDU 7, LDU2 A, PDU C, TDULC F. */
    val DUIDS = intArrayOf(0x0, 0x3, 0x5, 0x7, 0xA, 0xC, 0xF)
    private val NID_TABLE: LongArray by lazy {
        LongArray(4096 * DUIDS.size) { nidCodeword(it / DUIDS.size, DUIDS[it % DUIDS.size]) }
    }

    class Nid(val nac: Int, val duid: Int, val bitErrors: Int)

    /** [word63] = the first 63 NID bits as received (bit 62 first). Returns the nearest valid NID within 11 bit errors, or null. */
    fun decodeNid(word63: Long, nacHint: Int = -1): Nid? {
        var best = 99; var bi = -1
        val t = NID_TABLE
        if (nacHint in 0..4095) {
            for (k in DUIDS.indices) { val i = nacHint * DUIDS.size + k; val e = java.lang.Long.bitCount(word63 xor t[i]); if (e < best) { best = e; bi = i } }
            if (best <= 11) return Nid(bi / DUIDS.size, DUIDS[bi % DUIDS.size], best)
            best = 99; bi = -1
        }
        for (i in t.indices) { val e = java.lang.Long.bitCount(word63 xor t[i]); if (e < best) { best = e; bi = i } }
        return if (best <= 11) Nid(bi / DUIDS.size, DUIDS[bi % DUIDS.size], best) else null
    }
}
